\label{thm:main}
Let $\Gamma$ be a countable discrete group and let
$\sigma$ be a trace-preserving action of $\Gamma$ on a tracial von Neumann
algebra $(Q,\tau_Q)$ such
that
\begin{enumerate}
\item[\textup{(a)}] the action is pointwise weakly mixing relative to every proper $\Gamma$-factor of $(Q,\tau_Q)$, including
the trivial factor;
\item[\textup{(b)}] for every non-trivial $\Gamma$-factor $B$ of $(Q,\tau_Q)$,
the inclusion $B\subseteq Q$ is centrally $\Gamma$-free.
\end{enumerate}
Let ${\mathcal P}\subseteq Q\rtimes\Gamma$ be a $\Gamma$-invariant von
Neumann subalgebra. Then
\begin{enumerate}
\item[\textup{(i)}] if ${\mathcal P}\cap Q\neq{\mathbb C}1$, then
${\mathcal P}=({\mathcal P}\cap Q)\rtimes N$ for some $N\trianglelefteq\Gamma$;
\item[\textup{(ii)}] if $\mathbb{E}({\mathcal P})={\mathbb C}1$, then
${\mathcal P}\subseteq L(\Gamma)$; if moreover $\Gamma$ has the ISR property,
then ${\mathcal P}=L(N)$ for some $N\trianglelefteq\Gamma$.
\end{enumerate}

\label{lem:weak-zero-from-pairwise}
Let $\widehat{\mathcal H}$ be a Hilbert space and let $(\eta_k)_{k\in{\mathbb N}}\subseteq\widehat{\mathcal H}$ be a bounded sequence. Assume that $\langle\eta_k,\eta_\ell\rangle\to0$ as
$\max\{k,\ell\}\to\infty$, $k\neq\ell$. Then $\eta_k\to0$ weakly as $k$ tends to infinity.

\label{lem:commuting-square}
Let $(M,\tau)$ be a tracial von Neumann algebra, let $A,{\mathcal P}\subseteq M$ be von Neumann
subalgebras, and let $B={\mathcal P}\cap A$. The following conditions are equivalent.
\begin{enumerate}
\item[\textup{(i)}] $\mathbb{E}_A({\mathcal P})\subseteq{\mathcal P}$;
\item[\textup{(ii)}] $\mathbb{E}_{{\mathcal P}}(A)\subseteq A$;
\item[\textup{(iii)}] $\mathbb{E}_A\mathbb{E}_{{\mathcal P}}=\mathbb{E}_{{\mathcal P}}\mathbb{E}_A$.
\end{enumerate}
In this case $\mathbb{E}_A\mathbb{E}_{{\mathcal P}}=\mathbb{E}_{{\mathcal P}}\mathbb{E}_A=\mathbb{E}_B$. In particular,
$\mathbb{E}_A({\mathcal P})=B=\mathbb{E}_{{\mathcal P}}(A)$ and $\mathbb{E}_{{\mathcal P}}(a)=\mathbb{E}_B(a)$ for every $a\in A$,
and the diagram
\[
\begin{tikzcd}
M \arrow[r,"\mathbb{E}_{{\mathcal P}}"] \arrow[d,"\mathbb{E}_A"'] & {\mathcal P} \arrow[d,"\mathbb{E}_A"]\\
A \arrow[r,"\mathbb{E}_B"'] & B={\mathcal P}\cap A
\end{tikzcd}
\]
commutes in the sense that $\mathbb{E}_A\circ\mathbb{E}_{{\mathcal P}}=\mathbb{E}_B\circ\mathbb{E}_A$.

\label{cor:cs-crossed}
Let $\sigma$ be a trace-preserving action of $\Gamma$ on a tracial von Neumann algebra $(Q,\tau_Q)$ and let
${\mathcal P}\subseteq Q\rtimes_\sigma\Gamma$ be a $\Gamma$-invariant von Neumann subalgebra such that
$\mathbb{E}({\mathcal P})\subseteq{\mathcal P}$. Write $B=\mathbb{E}({\mathcal P})={\mathcal P}\cap Q$ as in
Remark~ 
    \IfBooleanTF{rem:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  . If $\sigma$ is pointwise weakly mixing relative to $B$, then
${\mathcal P}\subseteq B\rtimes\Gamma$.

To establish the claim, it is enough to show that $\mathbb{E}_{{\mathcal P}}(fu_s)=0$ whenever $s\in\Gamma$
and $f\in Q$ satisfies $\mathbb{E}_B(f)=0$. Assuming this, let
$x\in{\mathcal P}$ have Fourier coefficients $f_s=\mathbb{E}(xu_s^*)$, $s\in\Gamma$. For every $s\in\Gamma$
and every $f\in Q$ with $\mathbb{E}_B(f)=0$ we have
$\langle f_s,f\rangle=\tau\big((fu_s)^*x\big)=\langle x,\mathbb{E}_{{\mathcal P}}(fu_s)\rangle=0$.
Since such $f$ are dense in $L^2(Q,\tau_Q)\ominus L^2(B,\tau_Q)$, it follows that
$f_s\in L^2(B,\tau_Q)\cap Q=B$ for every $s\in\Gamma$, that is, $x\in B\rtimes\Gamma$.

It remains to prove that $\mathbb{E}_{{\mathcal P}}(fu_s)=0$ whenever $\mathbb{E}_B(f)=0$. For $s=e$,
this follows from Remark~ 
    \IfBooleanTF{rem:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  , since $\mathbb{E}_{{\mathcal P}}(f)=\mathbb{E}_B(f)=0$. For
$s\neq e$, we apply Theorem~ 
    \IfBooleanTF{thm:cs-engine}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   with $M=Q\rtimes_\sigma\Gamma$,
$\theta_h=\operatorname{Ad}(u_h)$ ($h \in \Gamma$), $A=Q$, $g=s$ and $w=u_s$; note that
$\theta_s(u_s)=u_s$.

The argument is the same as for Corollary~ 
    \IfBooleanTF{cor:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  . Let
$x=\sum_{t\in\Gamma}\lambda_t\otimes f_t\in{\mathcal P}$, with $f_t\in Q$. For $t\in\Gamma$ and $f\in Q$ with
$\mathbb{E}_B(f)=0$ we have
$\tau_Q(f^*f_t)=\langle x,\lambda_t\otimes f\rangle=\langle x,\mathbb{E}_{{\mathcal P}}(\lambda_t\otimes f)\rangle$,
so it is enough to show that $\mathbb{E}_{{\mathcal P}}(\lambda_t\otimes f)=0$. For $t=e$ this follows from
Lemma~ 
    \IfBooleanTF{lem:commuting-square}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  . For $t\neq e$, we apply Theorem~ 
    \IfBooleanTF{thm:cs-engine}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   with
$M=L(\Gamma)\bar\otimes Q$, the diagonal action $\theta$, $A=\mathbb{C}1\bar{\otimes}Q$, $g=t$ and
$w=\lambda_t\otimes1$; note that $\theta_t(\lambda_t\otimes1)=\lambda_{ttt^{-1}}\otimes1=\lambda_t\otimes1$
and $(1\otimes f)w=\lambda_t\otimes f$.

Since $\mathbb{E}({\mathcal P})={\mathbb C}1\subseteq{\mathcal P}$, the algebra ${\mathcal P}$ forms a commuting square with $Q$
(respectively, with $\mathbb{C}1\bar{\otimes}Q$), and the intersection is ${\mathbb C}1$. Weak mixing relative to ${\mathbb C}1$
is weak mixing, so Corollary~ 
    \IfBooleanTF{cor:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   (respectively, Corollary~ 
    \IfBooleanTF{cor:cs-tensor}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  )
gives ${\mathcal P}\subseteq{\mathbb C}1\rtimes\Gamma=L(\Gamma)$ (respectively, ${\mathcal P}\subseteq L(\Gamma)\bar\otimes{\mathbb C}1$).
In either case ${\mathcal P}$ is a $\Gamma$-invariant von Neumann subalgebra of $L(\Gamma)$, and the last
assertion is the definition of the ISR property.

By Lemma~ 
    \IfBooleanTF{lem:central-free-expectation}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  , $\mathbb{E}({\mathcal P})\subseteq{\mathcal P}$ and
$B'\cap(B\rtimes\Gamma)=Z(B)$. Corollary~ 
    \IfBooleanTF{cor:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   gives
$B\subseteq{\mathcal P}\subseteq B\rtimes\Gamma$. Since each $\sigma_s$, $s\neq e$, is
weakly mixing on $Q$, its restriction to $B$ is ergodic. Apply
Lemma~ 
    \IfBooleanTF{lem:groupoid-to-normal}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  .

\label{rem:open-case-cs}
Assume condition~(b) in Theorem~ 
    \IfBooleanTF{thm:main}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  . By
Lemma~ 
    \IfBooleanTF{lem:central-free-expectation}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   and Remark~ 
    \IfBooleanTF{rem:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  , ${\mathcal P}$ forms a commuting square with $Q$ whenever
${\mathcal P}\cap Q\neq{\mathbb C}1$, and the same holds trivially when $\mathbb{E}({\mathcal P})={\mathbb C}1$. Conversely, if ${\mathcal P}$
forms a commuting square with $Q$, then $\mathbb{E}({\mathcal P})={\mathcal P}\cap Q$ by
Remark~ 
    \IfBooleanTF{rem:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  , so either ${\mathcal P}\cap Q\neq{\mathbb C}1$ or $\mathbb{E}({\mathcal P})={\mathbb C}1$. Hence the case outside the subalgebra alternatives in parts~(i) and~(ii) of
Theorem~ 
    \IfBooleanTF{thm:main}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   is exactly the case in which ${\mathcal P}$ and $Q$ do not form a commuting square.

\label{rem:beyond}
If $\mathbb{E}({\mathcal P})\subseteq{\mathcal P}$, then $\mathbb{E}({\mathcal P})''=\mathbb{E}({\mathcal P})$, and
Corollary~ 
    \IfBooleanTF{cor:cs-crossed}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   gives the conclusion of Theorem~ 
    \IfBooleanTF{thm:gen}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 

without the ECI property. If $\mathbb{E}({\mathcal P})''=Q$, the conclusion is trivial.
In particular, for a prime p.m.p.~action, $\mathbb{E}({\mathcal P})''=L^\infty(X,\nu)$ as soon as
$\mathbb{E}({\mathcal P})\neq{\mathbb C}1$.

\label{rem:tensor-cs}
Lemma~ 
    \IfBooleanTF{lem:tensor-center-valued-character}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   shows that under the stated assumptions
$\mathbb{E}_{{\mathcal P}}$ preserves $\mathbb{C}1\bar{\otimes}L^\infty(X,\nu)$. By
Lemma~ 
    \IfBooleanTF{lem:commuting-square}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  , these algebras form a commuting square,
and
$${\mathcal P}\cap(\mathbb{C}1\bar{\otimes}L^\infty(X,\nu)) =\mathbb{E}_{{\mathcal P}}(\mathbb{C}1\bar{\otimes}L^\infty(X,\nu))=\mathbb{C}1\bar{\otimes} B=Z({\mathcal P}).$$

Since $Z({\mathcal P})$ is abelian, it is amenable. Since ${\mathcal P}$ is $\theta$-invariant,
$Z({\mathcal P})$ is also $\theta$-invariant. Apply Corollary~ 
    \IfBooleanTF{cor:amenable-tensor}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 

to $Z({\mathcal P})$.

As the amenable radical of $\Gamma$ is trivial, Corollary~ 
    \IfBooleanTF{cor:diagonal-tensor-center}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
   gives $Z({\mathcal P})\subseteq\mathbb{C}1\bar{\otimes}L^\infty(X,\nu)$. By
Lemma~ 
    \IfBooleanTF{lem:tensor-center-valued-character}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  , $Z({\mathcal P})=\mathbb{C}1\bar{\otimes} B$ for a $\Gamma$-invariant von
Neumann subalgebra $B\subseteqL^\infty(X,\nu)$. Theorem~ 
    \IfBooleanTF{thm:tensor-center-in-A}{\paper@unboxedref*{#2}}{ 
      \begingroup
      \edef\getrefbykeydefault{#2}{anchor}{}{\getrefbykeydefault{#2}{anchor}{}} 
      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  ,
including its one-point case, now gives
${\mathcal P}=L(N)\bar\otimes B$ for some $N\trianglelefteq\Gamma$.

\label{prop:direct-augmentation}
Let ${\mathbb F}_n$ be the nonabelian free group on $2\leq n\leq\infty$ generators,
and let $V=\mathbb Z{\mathbb F}_n$, regarded as an additive group.
There is a subgroup $H<V\times{\mathbb F}_n$ with the following properties.
\begin{enumerate}
\item $H$ is invariant under $(v,s)\mapsto(gv,gsg^{-1})$ for every $g\in{\mathbb F}_n$;
\item $\{0\}\neq H\cap V\neq V$;
\item $H\neq H_1\times H_2$ for all subgroups $H_1\leq V$ and $H_2\leq{\mathbb F}_n$;
\item in the tensor coordinates $L(V\times{\mathbb F}_n)\cong L({\mathbb F}_n)\bar\otimes L(V)$,
$L(H)\neq B_2\bar\otimes B_1$ for all von Neumann subalgebras
$B_1\subseteq L(V)=L^\infty(\mathbb T^{{\mathbb F}_n})$ and $B_2\subseteq L({\mathbb F}_n)$.
\end{enumerate}

The sets $R(C)$, $C\in\mathcal C$, are not needed for the conclusion about
$R_+=RP$, and are absent from
\cite[Lemma~17.4]{kechris2010global}; they are included here because the
conclusion about $R_-=PR$ is used in the case $\varepsilon=-1$ of
Proposition~ 
    \IfBooleanTF{prop:remove-fixed-points}{\paper@unboxedref*{#2}}{ 
      \begingroup
