      \expandafter\paper@styledref\getrefbykeydefault{#2}{anchor}{}.\@nil{#2} 
      \endgroup
    } 
  .

\label{prop:remove-fixed-points}
Fix an aperiodic transformation $T\in{\rm Aut}(X,\nu)$ and let $S\in{\rm Aut}(X,\nu)$. 


Let $n \in {\mathbb N}$ and let $v\in {\mathbb F}_2$ be a reduced word of length $n$ in
which $b^{\pm1}$ occurs. Suppose that $A\subseteq X$ is Borel and
$v_0^{T,S}(A),v_1^{T,S}(A),\ldots,v_{n-1}^{T,S}(A)$ are pairwise disjoint. Given a finite family $\mathcal C$ of Borel subsets of $X$,
there is $S'\in{\rm Aut}(X,\nu)$ such that
\begin{enumerate}[label=\textup{(\roman*)}]
\item $S'^{\pm1}(C)=S^{\pm1}(C)$ for every $C\in\mathcal C$;
\item $\nu(A\cap\text{Fix}(v^{T,S'}))=0$.
\end{enumerate}
